	depth = int32(1)
	goto _8
_4:
	;
	v15 = (*Tpacked_u32)(unsafe.Pointer((*TJSFunctionDef)(unsafe.Pointer(fd)).Fbyte_code.Fbuf + uintptr((*TJSFunctionDef)(unsafe.Pointer(fd)).Flast_opcode_pos) + uintptr(1))).Fv
	goto _16
